      await assertData(original);
    }
    assert.equal((await request('/api/projects/99999', 'PATCH', { name: 'Missing' })).status, 404);
    assert.equal((await request(projectPath, 'PATCH', { name: 'Mixed', archived: true })).status, 400);
    await assertData(original);
